def transform(grid):
    bg = grid[0][0]

    count = {}
    for row in grid:
        for cell in row:
            count[cell] = count.get(cell, 0) + 1

    candidates = [c for c in count if c != bg and count[c] % 3 == 0]

    if not candidates:
        return [[bg]]

    max_c = max(count[c] for c in candidates)
    selected = sorted([c for c in candidates if count[c] == max_c])

    h = max_c
    w = len(selected)
    out = [[0]*w for _ in range(h)]

    for i in range(w):
        c = selected[i]
        for j in range(h):
            out[j][i] = c

    return out
